def alternate_case(text):
    result = []
    upper = True
    for ch in text:
        if ch.isalpha():
            result.append(ch.upper() if upper else ch.lower())
            upper = not upper
        else:
            result.append(ch)
    return "".join(result)

def count_vowels_consonants(text):
    vowels = consonants = 0
    for ch in text:
        if ch.isascii() and ch.isalpha():
            if ch.lower() in "aeiou":
                vowels += 1
            else:
                consonants += 1
    return (vowels, consonants)

def is_phrase_palindrome(text):
    chars = [ch.lower() for ch in text if ch.isalnum()]
    return chars == chars[::-1]

def caesar_shift(text, shift):
    result = []
    for ch in text:
        if "a" <= ch <= "z":
            result.append(chr((ord(ch) - ord("a") + shift) % 26 + ord("a")))
        elif "A" <= ch <= "Z":
            result.append(chr((ord(ch) - ord("A") + shift) % 26 + ord("A")))
        else:
            result.append(ch)
    return "".join(result)

def capitalize_words(text):
    words = text.split(" ")
    return " ".join(word[:1].upper() + word[1:].lower() for word in words)

import re

def censor_words(text, banned):
    blocked = set(banned)

    def hide(match):
        word = match.group()
        return "*" * len(word) if word.lower() in blocked else word

    return re.sub(r"[A-Za-z]+", hide, text)

from itertools import groupby

def compress_runs(text):
    parts = []
    for ch, group in groupby(text):
        count = len(list(group))
        parts.append(ch if count == 1 else f"{ch}{count}")
    return "".join(parts)

from collections import Counter

def first_unique_char(text):
    counts = Counter(text)
    for ch in text:
        if counts[ch] == 1:
            return ch
    return ""

def mask_secret(secret, visible):
    hidden = max(len(secret) - visible, 0)
    return "*" * hidden + secret[hidden:]

def snake_to_camel(name):
    parts = [p for p in name.split("_") if p]
    if not parts:
        return ""
    first = parts[0].lower()
    rest = [p[0].upper() + p[1:].lower() for p in parts[1:]]
    return first + "".join(rest)

from itertools import zip_longest

def interleave_strings(first, second):
    pairs = zip_longest(first, second, fillvalue="")
    return "".join(a + b for a, b in pairs)

import string

def atbash(text):
    lower = string.ascii_lowercase
    upper = string.ascii_uppercase
    table = str.maketrans(lower + upper, lower[::-1] + upper[::-1])
    return text.translate(table)

def count_overlapping(text, pattern):
    if not pattern:
        return 0
    count = 0
    for i in range(len(text) - len(pattern) + 1):
        if text[i:i + len(pattern)] == pattern:
            count += 1
    return count

def dedupe_keep_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def rotate_right(items, k):
    if not items:
        return []
    k %= len(items)
    split = len(items) - k
    return items[split:] + items[:split]

def second_largest(nums):
    largest = second = None
    for n in nums:
        if largest is None or n > largest:
            largest, second = n, largest
        elif n != largest and (second is None or n > second):
            second = n
    return second

def running_max(nums):
    result = []
    best = None
    for n in nums:
        if best is None or n > best:
            best = n
        result.append(best)
    return result

def split_on_value(items, separator):
    groups = [[]]
    for item in items:
        if item == separator:
            groups.append([])
        else:
            groups[-1].append(item)
    return groups

def remove_adjacent_duplicates(items):
    result = []
    for item in items:
        if not result or result[-1] != item:
            result.append(item)
    return result

def window_sums(nums, k):
    if k > len(nums):
        return []
    total = sum(nums[:k])
    sums = [total]
    for i in range(k, len(nums)):
        total += nums[i] - nums[i - k]
        sums.append(total)
    return sums

def increasing_prefix(nums):
    if not nums:
        return []
    end = 1
    while end < len(nums) and nums[end] > nums[end - 1]:
        end += 1
    return nums[:end]

def merge_sorted(first, second):
    i = j = 0
    merged = []
    while i < len(first) and j < len(second):
        if first[i] <= second[j]:
            merged.append(first[i])
            i += 1
        else:
            merged.append(second[j])
            j += 1
    merged.extend(first[i:])
    merged.extend(second[j:])
    return merged

def swap_pairs(items):
    result = list(items)
    for i in range(0, len(result) - 1, 2):
        result[i], result[i + 1] = result[i + 1], result[i]
    return result

def fill_forward(values):
    result = []
    last = None
    for value in values:
        if value is not None:
            last = value
        result.append(last)
    return result

def group_consecutive(nums):
    groups = []
    for n in nums:
        if groups and n == groups[-1][-1] + 1:
            groups[-1].append(n)
        else:
            groups.append([n])
    return groups

def letter_frequency(text):
    counts = {}
    for ch in text.lower():
        if ch.isalpha():
            counts[ch] = counts.get(ch, 0) + 1
    return counts

