        return False
    digits = color[1:]
    return len(digits) in (3, 6) and all(c in string.hexdigits for c in digits)

import re

def username_valid(name):
    if not 3 <= len(name) <= 16:
        return False
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", name):
        return False
    return not name.endswith("_") and "__" not in name

def brackets_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def time_24h_valid(text):
    if len(text) != 5 or text[2] != ":":
        return False
    digits = text[:2] + text[3:]
    if not (digits.isascii() and digits.isdigit()):
        return False
    return int(text[:2]) <= 23 and int(text[3:]) <= 59

def date_valid(year, month, day):
    if not 1 <= month <= 12:
        return False
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return 1 <= day <= days_in_month[month - 1]

def slug_valid(slug):
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-")
    if not slug or not set(slug) <= allowed:
        return False
    if slug[0] == "-" or slug[-1] == "-":
        return False
    return "--" not in slug

def format_duration(seconds):
    hours, rest = divmod(seconds, 3600)
    minutes, secs = divmod(rest, 60)
    parts = []
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    if secs:
        parts.append(f"{secs}s")
    return " ".join(parts) if parts else "0s"

def ordinal(n):
    if n % 100 in (11, 12, 13):
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"

def format_table(rows):
    if not rows:
        return []
    widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]
    lines = []
    for row in rows:
        cells = [cell.ljust(width) for cell, width in zip(row, widths)]
        lines.append(" | ".join(cells).rstrip())
    return lines

def human_bytes(size):
    if size < 1024:
        return f"{size} B"
    value = size / 1024
    for unit in ["KB", "MB", "GB"]:
        if value < 1024:
            return f"{value:.1f} {unit}"
        value /= 1024
    return f"{value:.1f} TB"

def join_english(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + ", and " + items[-1]

def abbreviate_name(full_name):
    names = full_name.split()
    if not names:
        return ""
    initials = [name[0].upper() + "." for name in names[:-1]]
    return " ".join(initials + [names[-1].capitalize()])

def truncate_text(text, max_length):
    if len(text) <= max_length:
        return text
    return text[:max_length - 3].rstrip() + "..."

def to_roman(number):
    symbols = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
               (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
               (5, "V"), (4, "IV"), (1, "I")]
    result = []
    for value, symbol in symbols:
        count, number = divmod(number, value)
        result.append(symbol * count)
    return "".join(result)

def zero_pad_ids(ids):
    if not ids:
        return []
    width = max(len(str(n)) for n in ids)
    return [str(n).zfill(width) for n in ids]

def progress_bar(done, total, width):
    if total == 0:
        done = total = 1
    filled = width * done // total
    percent = 100 * done // total
    return "[" + "#" * filled + "-" * (width - filled) + f"] {percent}%"

def numbered_lines(items):
    width = len(str(len(items)))
    return [f"{i:>{width}}. {item}" for i, item in enumerate(items, start=1)]
